const express = require('express');
const bodyParser = require('body-parser');
const fs = require('fs');
const path = require('path');
const morgan = require('morgan');

const app = express();
const PORT = 3000;

// Middleware
app.use(bodyParser.json());
app.use(morgan('dev'));

// Log file path
const logFilePath = path.join(__dirname, 'logs', 'loginAttempts.log');

// Ensure logs directory exists
if (!fs.existsSync(path.join(__dirname, 'logs'))) {
  fs.mkdirSync(path.join(__dirname, 'logs'));
}

// Simple user database (for demo purposes)
const users = {
  'user1': 'password1',
  'user2': 'password2'
};

// Helper function to log login attempts
function logLoginAttempt(username, success) {
  const timestamp = new Date().toISOString();
  const logEntry = `${timestamp} - Username: ${username} - Success: ${success}\n`;
  fs.appendFile(logFilePath, logEntry, (err) => {
    if (err) {
      console.error('Failed to log login attempt:', err);
    }
  });
}

// Routes
app.get('/', (req, res) => {
  res.send(`
    <h1>Login</h1>
    <form method="POST" action="/login">
      <label>Username: <input type="text" name="username" /></label><br/>
      <label>Password: <input type="password" name="password" /></label><br/>
      <button type="submit">Login</button>
    </form>
  `);
});

// To parse URL-encoded form data
app.use(bodyParser.urlencoded({ extended: true }));

app.post('/login', (req, res) => {
  const { username, password } = req.body;
  const userPassword = users[username];

  if (userPassword && userPassword === password) {
    logLoginAttempt(username, true);
    res.send(`<h2>Login successful! Welcome, ${username}.</h2>`);
  } else {
    logLoginAttempt(username || 'unknown', false);
    res.status(401).send('<h2>Login failed. Invalid username or password.</h2>');
  }
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
